mapper.select:
SELECT c.id, c.document_id, c.content, d.title, d.source, ROUND(MATCH(c.content) AGAINST(#{query} IN NATURAL LANGUAGE MODE), 4) AS score FROM kb_chunk c JOIN kb_document d ON d.id = c.document_id AND d.status = 'INGESTED' WHERE MATCH(c.content) AGAINST(#{query} IN NATURAL LANGUAGE MODE) > 0
AND ROUND(MATCH(c.content) AGAINST(#{query} IN NATURAL LANGUAGE MODE), 4) >= #{minScore}
ORDER BY score DESC LIMIT #{limit}
